import sys

data = sys.stdin.buffer.read().split()
n = int(data[0])
q = int(data[1])
# every component keeps an explicit dictionary of node -> tally relative to the
# component, and merging shifts the smaller dictionary into the larger one
root_of = list(range(n + 1))
comp = [None] * (n + 1)
for i in range(1, n + 1):
    comp[i] = {i: 0}
out = []
pos = 2
for _ in range(q):
    if data[pos] == b"1":
        u = int(data[pos + 1]); v = int(data[pos + 2]); d = int(data[pos + 3])
        pos += 4
        ru = root_of[u]; rv = root_of[v]
        if ru == rv:
            out.append("1" if comp[ru][u] - comp[ru][v] == d else "0")
        else:
            a = comp[ru]; b = comp[rv]
            if len(a) >= len(b):
                shift = a[u] - d - b[v]
                for x, val in b.items():
                    a[x] = val + shift
                    root_of[x] = ru
                comp[rv] = None
            else:
                shift = b[v] + d - a[u]
                for x, val in a.items():
                    b[x] = val + shift
                    root_of[x] = rv
                comp[ru] = None
            out.append("1")
    else:
        u = int(data[pos + 1]); v = int(data[pos + 2])
        pos += 3
        ru = root_of[u]
        if ru == root_of[v]:
            out.append(str(comp[ru][u] - comp[ru][v]))
        else:
            out.append("?")
sys.stdout.write("\n".join(out) + "\n")
